DROP TABLE IF EXISTS `teledata`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teledata` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `company_name` varchar(255) NOT NULL,
  `mobile` varchar(20) NOT NULL,
  `mobile_2` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `location` text,
  `contact_person` varchar(255) DEFAULT NULL,
  `category` int DEFAULT NULL,
  `staff` int unsigned DEFAULT NULL,
  `assign` int unsigned DEFAULT NULL,
  `rowdata_staff` int NOT NULL,
  `transfer_staff_id` int NOT NULL,
  `source` varchar(100) DEFAULT NULL,
  `status` int NOT NULL,
  `prev_status` int NOT NULL,
  `approve_proposel` int NOT NULL,
  `status_action` int NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `transfer_date` date NOT NULL,
  `document` varchar(100) NOT NULL,
  `employee` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7797 DEFAULT CHARSET=utf8mb3;
