-- Table structure for table `transactions_quotationapproval`
--

DROP TABLE IF EXISTS `transactions_quotationapproval`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions_quotationapproval` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signed_by` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signed_at` datetime(6) DEFAULT NULL,
  `signature_ref` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signature_hash` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `otp_hash` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `otp_sent_at` datetime(6) DEFAULT NULL,
  `otp_expires_at` datetime(6) DEFAULT NULL,
  `rejection_reason` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `quotation_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint NOT NULL,
  `otp_attempts` int unsigned NOT NULL,
